"""
offline_pcf_data.py
===================
Isoliertes Modul fuer den temporaeren Offline-Modus (Datenstand Q4 2026).

Enthaelt den vollstaendig eingebetteten PCF-Referenzdatenbestand (9.635 WAGO-Artikel,
Einheit: kg CO2e pro 1 Stueck) sowie die indizierte Lookup- und Validierungslogik.

WICHTIG:
- Zur Laufzeit wird KEINE externe Excel-, JSON- oder Datenbankdatei geladen.
- Es werden KEINE Netzwerk-/API-Aufrufe durchgefuehrt.
- Zum spaeteren Entfernen des Offline-Modus kann dieses Modul geloescht werden.
"""

from __future__ import annotations

import math
import re
import sys
from typing import Any, Callable, Dict, Iterable, Optional, Tuple

# Status-Konstanten (synchron mit aas_pcf_query.py, ohne Zirkel-Import)
STATUS_PCF_AVAILABLE          = "PCF available"
STATUS_NOT_YET_AVAILABLE      = "Not yet available"
INTERNAL_STATUS_PCF_AVAILABLE = "PCF available"
INTERNAL_STATUS_NOT_FOUND     = "Article not found"

DEFAULT_OFFLINE_PCF_UNIT      = "kg CO2e"
DEFAULT_OFFLINE_REF_UNIT      = "piece"
DEFAULT_OFFLINE_REF_QUANTITY  = 1.0
OFFLINE_DATA_SOURCE_LABEL     = "Embedded Snapshot (Q4 2026)"
OFFLINE_EXCEL_HEADER_NOTE     = (
    "The provided PCF values are based on a fixed data snapshot from Q4 2026 "
    "and are not automatically updated. Current PCF values are available in the WAGO AAS Portal."
)

_article_parser_fn: Optional[Callable[[Any], Dict[str, Any]]] = None


def register_article_parser(parser_fn: Callable[[Any], Dict[str, Any]]) -> None:
    """Registriert die Artikelnummern-Normalisierungsfunktion aus aas_pcf_query."""
    global _article_parser_fn
    _article_parser_fn = parser_fn


def _parse_article(value: Any) -> Dict[str, Any]:
    if _article_parser_fn is not None:
        return _article_parser_fn(value)
    for mod_name in ("aas_pcf_query", "__main__"):
        mod = sys.modules.get(mod_name)
        fn = getattr(mod, "parse_article_number", None) if mod else None
        if callable(fn):
            return fn(value)
    from aas_pcf_query import parse_article_number
    return parse_article_number(value)

# ── Konstanten fuer den Offline-Modus & UI-Hinweis ───────────────────────────

OFFLINE_SNAPSHOT_VERSION = "Q4 2026"
