OFFLINE_NOTICE_TEXT      = (
    "Im Offline-Modus werden PCF-Werte aus einem fest hinterlegten Datenbestand "
    "von Q4 2026 verwendet. Diese Werte werden nicht automatisch aktualisiert. "
    "Aktuelle PCF-Werte finden Sie im WAGO AAS Portal."
)
OFFLINE_PORTAL_URL       = "https://aas.wago.com/"

