def _build_kz_alias_index(data: Dict[str, float]) -> Dict[str, float]:
    """
    Erzeugt zusaetzliche Lookup-Aliase fuer K/Z-Varianten mit 3 vs. 4 Ziffern
    nach dem Bindestrich (z. B. K000-002 <-> K000-0002), sofern eindeutig.
    """
    aliases: Dict[str, float] = {}
    for k, v in data.items():
        k4 = re.sub(r"/([KZ]\d{3})-(\d{3})(?=/|$)", r"/\1-0\2", k)
        if k4 != k and k4 not in data:
            aliases[k4] = v
        k3 = re.sub(r"/([KZ]\d{3})-0(\d{3})(?=/|$)", r"/\1-\2", k)
        if k3 != k and k3 not in data:
            aliases[k3] = v
    return aliases


_KZ_ALIAS_DATA: Dict[str, float] = _build_kz_alias_index(EMBEDDED_PCF_DATA)


def validate_and_index_pcf_records(
    records: Iterable[Tuple[Any, Any]],
    rel_tol: float = 1e-9,
    abs_tol: float = 1e-12,
) -> Dict[str, float]:
    """
    Validiert und indiziert (article_number, pcf_value)-Datensaetze anhand der
    normalisierten WAGO-Artikelnummer.

    - Identische Duplikate (auch in unterschiedlicher Darstellung wie 221-412 und 0221-0412)
      werden zusammengefasst.
    - Widerspruechliche PCF-Werte fuer denselben normalisierten Artikel loesen einen
      ValueError aus, statt stillschweigend ueberschrieben zu werden.
    """
    index: Dict[str, float] = {}
    for raw_art, raw_pcf in records:
        parsed = _parse_article(raw_art)
        if not parsed["original"] or not parsed["is_valid"]:
            continue
        if raw_pcf is None or isinstance(raw_pcf, bool):
            continue
        s_pcf = str(raw_pcf).strip().replace(",", ".")
        if not s_pcf or s_pcf.lower() in ("nan", "none", "not available", "not yet available"):
            continue
        try:
            pcf_val = float(s_pcf)
        except ValueError:
            continue
        if math.isnan(pcf_val) or math.isinf(pcf_val):
            continue

        canon = parsed["canonical"]
        if canon in index:
            existing = index[canon]
            if not math.isclose(existing, pcf_val, rel_tol=rel_tol, abs_tol=abs_tol):
                raise ValueError(
                    f"Conflicting PCF values for article {canon!r} (from {raw_art!r}): "
                    f"{existing} vs {pcf_val}"
                )
        else:
            index[canon] = pcf_val
    return index


def get_offline_pcf_result(
    article_number: Any,
    dataset: Optional[Dict[str, float]] = None,
) -> Dict[str, Any]:
    """
    Fragt den PCF-Wert fuer eine WAGO-Artikelnummer ausschliesslich aus dem
    eingebetteten Q4-2026-Datenbestand ab (ohne API-/Netzwerkzugriff).

    Gibt dieselbe Ergebnisstruktur wie get_pcf_result() im Online-Modus zurueck.
    """
    parsed = _parse_article(article_number)
    if not parsed["original"]:
        return {
            "pcf": None,
            "unit": "",
            "reference_unit": "",
            "reference_quantity": None,
            "status": STATUS_NOT_YET_AVAILABLE,
            "internal_status": INTERNAL_STATUS_NOT_FOUND,
            "article_short": "",
            "article_long": "",
            "source": OFFLINE_DATA_SOURCE_LABEL,
        }

    canonical = parsed["canonical"]
    short_art = parsed["short"]
    long_art  = parsed["long"]

    source_data = EMBEDDED_PCF_DATA if dataset is None else dataset
    pcf_val = source_data.get(canonical)
    if pcf_val is None and dataset is None:
        pcf_val = _KZ_ALIAS_DATA.get(canonical)

    if pcf_val is not None:
        return {
            "pcf": pcf_val,
            "unit": DEFAULT_OFFLINE_PCF_UNIT,
            "reference_unit": DEFAULT_OFFLINE_REF_UNIT,
            "reference_quantity": DEFAULT_OFFLINE_REF_QUANTITY,
            "status": STATUS_PCF_AVAILABLE,
            "internal_status": INTERNAL_STATUS_PCF_AVAILABLE,
            "article_short": short_art,
            "article_long": long_art,
            "source": OFFLINE_DATA_SOURCE_LABEL,
        }

    return {
        "pcf": None,
        "unit": "",
        "reference_unit": "",
        "reference_quantity": None,
        "status": STATUS_NOT_YET_AVAILABLE,
        "internal_status": INTERNAL_STATUS_NOT_FOUND,
        "article_short": short_art,
        "article_long": long_art,
        "source": OFFLINE_DATA_SOURCE_LABEL,
    }


def get_offline_pcf(
    article_number: Any,
    dataset: Optional[Dict[str, float]] = None,
) -> Optional[float]:
    """Gibt nur den PCF-Wert (float | None) aus dem eingebetteten Datenbestand zurueck."""
    return get_offline_pcf_result(article_number, dataset=dataset)["pcf"]
